#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;
const int MAX_STATE = (1 << 20) + 5;

int n, fullMask, result;
int firstDP[MAX_STATE], secondDP[MAX_STATE];
int constraint[10][10], matrix[10][10], tripleBit[10][10][10];

long long modPow(long long base, long long exp) {
    long long res = 1;
    while (exp) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long modInverse(long long x) {
    return modPow(x, MOD - 2);
}

bool checkTriple(int a, int b, int c) {
    int vals[3] = {a, b, c};
    int order[3] = {0, 1, 2};
    do {
        if (constraint[vals[order[0]]][1] && 
            constraint[vals[order[1]]][2] && 
            constraint[vals[order[2]]][3]) {
            return true;
        }
    } while (next_permutation(order, order + 3));
    return false;
}

void firstPass(int coef, int r, int c) {
    if (r == 7 && c == 1) {
        int state = 0;
        for (int i = 1; i <= 6; ++i)
            for (int j = i + 1; j <= 6; ++j)
                for (int k = j + 1; k <= 6; ++k)
                    if (checkTriple(i, j, k)) {
                        int x = 1;
                        while (x == i || x == j || x == k) ++x;
                        int y = x + 1;
                        while (y == i || y == j || y == k) ++y;
                        int z = y + 1;
                        while (z == i || z == j || z == k) ++z;
                        state |= tripleBit[x][y][z];
                    }
        firstDP[state] = (firstDP[state] + coef) % MOD;
        return;
    }

    constraint[r][c] = 1;
    if (c == 3) firstPass(1LL * coef * matrix[r][c] % MOD, r + 1, 1);
    else firstPass(1LL * coef * matrix[r][c] % MOD, r, c + 1);
    constraint[r][c] = 0;

    if (c == 3) firstPass(1LL * coef * (MOD + 1 - matrix[r][c]) % MOD, r + 1, 1);
    else firstPass(1LL * coef * (MOD + 1 - matrix[r][c]) % MOD, r, c + 1);
}

void secondPass(int coef, int r, int c) {
    if (r == 7 && c == 4) {
        int state = 0;
        for (int i = 1; i <= 6; ++i)
            for (int j = i + 1; j <= 6; ++j)
                for (int k = j + 1; k <= 6; ++k)
                    if (checkTriple(i, j, k)) state |= tripleBit[i][j][k];
        secondDP[state] = (secondDP[state] + coef) % MOD;
        result = (result + 1LL * firstDP[fullMask ^ state] * coef) % MOD;
        return;
    }

    constraint[r][c - 3] = 1;
    if (c == 6) secondPass(1LL * coef * matrix[r][c] % MOD, r + 1, 4);
    else secondPass(1LL * coef * matrix[r][c] % MOD, r, c + 1);
    constraint[r][c - 3] = 0;

    if (c == 6) secondPass(1LL * coef * (MOD + 1 - matrix[r][c]) % MOD, r + 1, 4);
    else secondPass(1LL * coef * (MOD + 1 - matrix[r][c]) % MOD, r, c + 1);
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            int temp;
            scanf("%d", &temp);
            matrix[i][j] = 1LL * temp * modInverse(100) % MOD;
        }
    for (int i = n + 1; i <= 6; ++i) matrix[i][i] = 1;

    int bitIdx = 0;
    for (int i = 1; i <= 6; ++i)
        for (int j = i + 1; j <= 6; ++j)
            for (int k = j + 1; k <= 6; ++k)
                tripleBit[i][j][k] = 1 << bitIdx++;

    firstPass(1, 1, 1);
    fullMask = (1 << 20) - 1;

    for (int b = 0; b < 20; ++b)
        for (int s = 0; s <= fullMask; ++s)
            if (s >> b & 1)
                firstDP[s] = (firstDP[s] + firstDP[s ^ (1 << b)]) % MOD;

    secondPass(1, 1, 4);
    result = (MOD + 1 - result) % MOD;
    printf("%d\n", result);
    return 0;
}
